/**
 * @param {string} s
 * @param {string} t
 * @return {string}
 */
var minWindow = function (s = "ADOBECODEBANC", t = "ABC") {
    if (s.length < t.length) return "";

    let min = Infinity, t_chars = {}, need = 0, left = 0, right = left + 1;

    for (const char of t) {
        t_chars[char] = (t_chars[char] || 0) + 1;
    }

    for (const key in t_chars) {
        need += t_chars[key]
    }

    console.log(need)
    while (right <= s.length) {
        let slice = s.slice(left, right), has = 0, wndw = {};

        for (const sl of slice) {
            if (t.includes(sl)) has++;
        }

        if (has >= need && (min === Infinity || min.length > slice.length)) min = slice;

        has >= need ? left++ : right++;
    }

    return min === Infinity ? "" : min;
};


// console.log("\n========minWindow()========")
console.log(minWindow());
console.log("\n========minWindow('a', 'a')========")
console.log(minWindow("a", "a"));
